# WAR ARENA - Expose ALL GMGN fields in trending stats - Installer
# Backend now passes every confirmed GMGN field (volume, ATH, burn, lock,
# open-source, mint/freeze renounce, bluechip, bot rate, snipers, launchpad,
# creator, socials, price changes, token age...) into the report stats.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-full-stats.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - full stats installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/integration/gmgnTrendingSource.ts" ""

npm run build; if ($LASTEXITCODE -ne 0){ throw "build failed" }
Write-Host ""; Write-Host "Backend rebuilt with full stats. Restart: npm start" -ForegroundColor Green
